  const panel = w.docNumPanelEl("invoice");
  panel.querySelectorAll("[data-dn]").forEach((el) => (el.value = ""));
  $("#dnInvoiceShipmentPick").value = "sx1";
  w.isiOtomatisDariJadwal();
