t("migrasi database peran finance ikut di paket", () => {
  const sql = fs.readFileSync(path.join(ROOT, "migration-role-finance.sql"), "utf8");
  ["'finance'", "document_numbers", "for select to authenticated", "drop policy if exists"].forEach((k) => {
    if (!sql.includes(k)) throw new Error("migrasi tidak memuat " + k);
  });
  // Finance HANYA membaca: tidak ada kebijakan tulis untuknya.
  const tanpaKomentar = sql.replace(/\/\*[\s\S]*?\*\//g, "").replace(/--.*$/gm, "");
  if (/for (insert|update|delete|all) to authenticated/i.test(tanpaKomentar)) throw new Error("migrasi memberi finance hak menulis");
  // Aman dijalankan ulang, dan tidak menyentuh fungsi khusus EXIM.
  if (/create policy (?!"finance )/i.test(tanpaKomentar)) throw new Error("migrasi membuat kebijakan di luar milik finance");
  if (/next_document_number|set_document_counter|delete_document_number|admin_/.test(tanpaKomentar))
    throw new Error("migrasi menyentuh fungsi yang harus tetap khusus EXIM");
});
t("migrasi tanda bayar finance ikut di paket: SATU fungsi, tanpa kebijakan / hak tabel baru, hanya paidAt & paidBy", () => {
  const sql = fs.readFileSync(path.join(ROOT, "migration-finance-tanda-bayar.sql"), "utf8");
  const isi = sql.replace(/\/\*[\s\S]*?\*\//g, "").replace(/--.*$/gm, "");
  [
    "create or replace function public.set_fund_paid(p_id text, p_paid_at date)",
    "security definer",
    "set search_path = public",
    "v_peran not in ('exim', 'finance')",
    "revoke all on function public.set_fund_paid(text, date) from public",
    "grant execute on function public.set_fund_paid(text, date) to authenticated",
  ].forEach((k) => {
    if (!isi.includes(k)) throw new Error("migrasi tidak memuat " + k);
  });
  // Tidak ada kebijakan atau hak tabel yang ikut dibuka.
  if (/\b(create|alter|drop) policy\b|grant\s+(select|insert|update|delete|all)\b/i.test(isi))
    throw new Error("migrasi mengubah kebijakan / hak tabel");
  // Yang ditulis hanya payload Pengajuan Dana, dan hanya dua kunci status bayar.
  eq([...isi.matchAll(/\bupdate\s+public\.(\w+)/gi)].map((m) => m[1]).join(","), "document_numbers,document_numbers", "tabel yang ditulis:");
  eq([...isi.matchAll(/\bset\s+(\w+)\s*=/gi)].map((m) => m[1]).join(","), "search_path,payload,payload", "kolom yang ditulis:");
  eq((isi.match(/doc_type = 'fund'/g) || []).length, 2, "hanya Pengajuan Dana:");
  if (!/- 'paidAt' - 'paidBy'/.test(isi)) throw new Error("membatalkan bukan menghapus paidAt & paidBy");
  if (!/jsonb_build_object\('paidAt', to_char\(p_paid_at, 'YYYY-MM-DD'\), 'paidBy', v_nama\)/.test(isi))
    throw new Error("menandai lunas menulis kunci lain");
});
t("migrasi database peran marketing ikut di paket", () => {
  const sql = require("fs").readFileSync(require("path").join(__dirname, "..", "migration-role-marketing.sql"), "utf8");
  ["'marketing'", "peran_saya", "next_document_number"].forEach((k) => {
    if (!sql.includes(k)) throw new Error("migrasi tidak memuat " + k);
  });
  // Yang SENGAJA tidak dibuka tidak boleh ikut disunting migrasinya.
  const bag4 = sql.slice(sql.indexOf("-- ---- 4."), sql.indexOf("-- ---- 5."));
  if (/proname (in \(|= ')[^)]*(delete_document_number|set_document_counter|admin_)/.test(bag4))
    throw new Error("migrasi menyunting fungsi yang harus tetap khusus EXIM");
  // Marketing tidak mengajukan nomor: tidak ada kebijakan INSERT untuknya,
  // dan yang dibuat versi sebelumnya dicabut.
  if (/for insert to authenticated[\s\S]{0,80}peran_saya\(\) = 'marketing'/.test(sql.slice(0, sql.indexOf("-- ---- 5."))))
    throw new Error("migrasi masih memberi marketing hak menambah nomor");
  if (!/drop policy if exists "marketing tambah nomor dokumen"/.test(sql))
    throw new Error("hak tambah nomor dari versi sebelumnya tidak dicabut");
  // Marketing juga tidak mengubah isian: kebijakan UPDATE-nya dicabut.
  if (/for update to authenticated[\s\S]{0,80}peran_saya\(\) = 'marketing'/.test(sql))
    throw new Error("migrasi masih memberi marketing hak mengubah isian");
  if (!/drop policy if exists "marketing ubah nomor dokumen"/.test(sql))
    throw new Error("hak ubah isian dari versi sebelumnya tidak dicabut");
});

