    w.loadShipments = async () => {};
    w.goBackToList = () => {};
    $("#fEtd").value = "2026-08-20";
    $("#fEta").value = "2026-08-30";
    w.eval('draftItems = [Object.assign(newItem(), { namaBarang: "SEGMENT MOLD" })]');
    $("#fHouseBL").value = "HBL-001";
    $("#confirmTitle").textContent = "";
