      eq(w.eval("mstSusun().find((b) => b.no === 58).terpakai"), 3, "terpakai baris 58 tetap 3:");
      eq(rinci58().querySelectorAll(".mst-rinci-tabel > tbody > tr").length, 3, "rincian tiga PIB:");
