      const daftar = [];
      [["A", ""], ["B", "2026-01-02"], ["A", "2026-01-01"], ["", "2026-01-03"], [" C ", "2026-01-04"]].forEach(([n, d]) => w.tambahDokumenPengiriman(daftar, n, d));
